#!/usr/bin/env python3
"""Standalone signed six-component terminal endpoint audit v0.9.28."""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import importlib.util
import json
import platform
import sys
import time
from decimal import Decimal, getcontext
from pathlib import Path
from typing import Any

VERSION = "0.9.28"
TITLE = "GEOMETRIC-FLOW SIGNED SIX-COMPONENT THIRD-CHART TERMINAL ENDPOINT BOX"
EMBEDDED_V0927_SHA256 = "7582eb9431d03ab6c66102977590fd5f827e38cadb1b8944833ca4328db629b5"
EMBEDDED_V0927_GZIP_B64 = ""
getcontext().prec = 90


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def sha256_json(value: Any) -> str:
    raw = json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    return hashlib.sha256(raw).hexdigest()


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    tmp.replace(path)


def materialize(path: Path) -> Path:
    raw = gzip.decompress(base64.b64decode(EMBEDDED_V0927_GZIP_B64))
    if hashlib.sha256(raw).hexdigest() != EMBEDDED_V0927_SHA256:
        raise RuntimeError("embedded v0.9.27 source hash mismatch")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    return path.resolve()


def load_module(path: Path):
    spec = importlib.util.spec_from_file_location("embedded_geometric_flow_v0927", path)
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load embedded v0.9.27")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def dec(value: Any, label: str) -> Decimal:
    result = Decimal(str(value))
    if not result.is_finite():
        raise ValueError(f"{label} is non-finite")
    return result


def six(values: Any, label: str) -> list[Decimal]:
    if not isinstance(values, list) or len(values) != 6:
        raise ValueError(f"{label} must contain six entries")
    return [dec(v, f"{label}[{i}]") for i, v in enumerate(values)]


def parse() -> tuple[argparse.Namespace, list[str]]:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", default="response_fibre_third_chart_endpoint_v0_9_28_results")
    return parser.parse_known_args()


def run(args: argparse.Namespace) -> dict[str, Any]:
    started = time.time()
    out = Path(args.outdir).resolve()
    out.mkdir(parents=True, exist_ok=True)
    embedded = materialize(out / "embedded_sources" / "response_fibre_third_chart_finite_continuation_v0_9_27_standalone.py")
    v0927 = load_module(embedded)
    base_out = out / "v0927_formal_base"
    base = v0927.run(argparse.Namespace(outdir=str(base_out), steps=None, max_search_steps=100000))
    if base.get("all_scientific_gates_pass") is not True or base.get("third_chart_finite_continuation_certified") is not True:
        raise RuntimeError("embedded v0.9.27 finite continuation did not pass")

    frame_path = base_out / "v0926_formal_base" / "v0925_third_chart_chain" / "third_frame_arb_certificate.json"
    picard_candidates = list(base_out.rglob("intrinsic_picard_microstep_certificate.json"))
    selected = []
    for path in picard_candidates:
        data = json.loads(path.read_text(encoding="utf-8"))
        if data.get("v0922_signed_field_export_coordinate_system") == "v0.9.26-third-recentered-intrinsic-tangent":
            selected.append((path, data))
    if len(selected) != 1:
        raise RuntimeError(f"expected one third-chart signed-field certificate, found {len(selected)}")
    picard_path, picard = selected[0]
    frame = json.loads(frame_path.read_text(encoding="utf-8"))
    continuation_path = Path(base["certificate"])
    continuation = json.loads(continuation_path.read_text(encoding="utf-8"))

    lower0 = six(frame["transformed_endpoint_box"]["lower"], "initial lower")
    upper0 = six(frame["transformed_endpoint_box"]["upper"], "initial upper")
    field_lo = six(picard.get("v0922_signed_intrinsic_field_component_lower"), "field lower")
    field_hi = six(picard.get("v0922_signed_intrinsic_field_component_upper"), "field upper")
    field_mid = six(picard.get("v0922_signed_intrinsic_field_component_midpoints"), "field midpoint")
    field_rad = six(picard.get("v0922_signed_intrinsic_field_component_radii"), "field radius")
    steps = int(base["requested_steps"])
    h = dec(picard.get("certified_time_step"), "time step")
    total_time = h * Decimal(steps)
    scalar_radius = dec(base["final_requested_radius"], "scalar reachable radius")
    domain_radius = dec(base["inner_domain_radius"], "inner domain radius")

    endpoint_lower = [lower0[i] + total_time * field_lo[i] for i in range(6)]
    endpoint_upper = [upper0[i] + total_time * field_hi[i] for i in range(6)]
    endpoint_center = [(endpoint_lower[i] + endpoint_upper[i]) / Decimal(2) for i in range(6)]
    endpoint_radius = [(endpoint_upper[i] - endpoint_lower[i]) / Decimal(2) for i in range(6)]
    formula_center = [total_time * field_mid[i] + (lower0[i] + upper0[i]) / Decimal(2) for i in range(6)]
    formula_radius = [(upper0[i] - lower0[i]) / Decimal(2) + total_time * field_rad[i] for i in range(6)]
    max_abs = max(max(abs(endpoint_lower[i]), abs(endpoint_upper[i])) for i in range(6))
    interval_ordered = all(endpoint_lower[i] <= endpoint_upper[i] for i in range(6))
    # The signed-field midpoint/radius arrays are JSON binary64 exports while
    # lower/upper are independently outward serialized.  Their pre-integration
    # discrepancy is at most a few 1e-17; after T=2.63e-12 this contributes
    # below 1e-28.  This 1e-27 audit tolerance covers only that serialization
    # difference and is fifteen orders below the endpoint-box radii.
    serialization_tolerance = Decimal("1e-27")
    formula_consistent = all(
        abs(endpoint_center[i] - formula_center[i]) < serialization_tolerance
        and abs(endpoint_radius[i] - formula_radius[i]) < serialization_tolerance
        for i in range(6)
    )
    signed_resolved = any(field_lo[i] > 0 or field_hi[i] < 0 for i in range(6))

    gates = {
        "embedded_v0927_hash_exact": sha256_file(embedded) == EMBEDDED_V0927_SHA256,
        "v0927_263_step_finite_continuation": base.get("maximum_steps_under_uniform_bounds") == 263 and steps == 263,
        "third_signed_field_intervals_present": len(field_lo) == len(field_hi) == 6,
        "third_signed_field_intervals_ordered": all(field_lo[i] <= field_hi[i] for i in range(6)),
        "at_least_one_field_component_sign_resolved": signed_resolved,
        "six_component_endpoint_intervals_ordered": interval_ordered,
        "midpoint_radius_formula_consistent": formula_consistent,
        "endpoint_box_contained_in_v0927_scalar_tube": max_abs <= scalar_radius,
        "endpoint_box_strictly_inside_third_inner_domain": max_abs < domain_radius,
        "certificate_bound_to_v0927": continuation.get("maximum_certified_steps") == 263,
    }
    passed = all(gates.values())
    certificate = {
        "schema": "geometric-flow/third-chart-signed-terminal-endpoint/v0.9.28",
        "generator_version": VERSION,
        "coordinate_system": "v0.9.26-third-recentered-intrinsic-tangent",
        "embedded_v0927_sha256": EMBEDDED_V0927_SHA256,
        "v0927_summary_sha256": sha256_file(base_out / "run_summary.json"),
        "v0927_continuation_certificate_sha256": sha256_file(continuation_path),
        "third_frame_certificate_sha256": sha256_file(frame_path),
        "third_picard_certificate_sha256": sha256_file(picard_path),
        "step_count": steps,
        "time_step": str(h),
        "total_certified_time": str(total_time),
        "initial_endpoint_box": {"lower": [str(x) for x in lower0], "upper": [str(x) for x in upper0]},
        "uniform_signed_field": {
            "lower": [str(x) for x in field_lo], "upper": [str(x) for x in field_hi],
            "midpoint": [str(x) for x in field_mid], "radius": [str(x) for x in field_rad],
        },
        "terminal_endpoint_box": {
            "center": [str(x) for x in endpoint_center],
            "component_radius": [str(x) for x in endpoint_radius],
            "lower": [str(x) for x in endpoint_lower],
            "upper": [str(x) for x in endpoint_upper],
        },
        "maximum_endpoint_absolute_coordinate": str(max_abs),
        "v0927_scalar_reachable_radius": str(scalar_radius),
        "inner_domain_radius": str(domain_radius),
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "claim_boundary": "signed uniform-field integral endpoint enclosure; its center is an interval-enclosure convention, not a validated sharp trajectory midpoint",
    }
    cert_path = out / "third_chart_signed_terminal_endpoint_certificate.json"
    atomic_json(cert_path, certificate)
    result = {
        "title": TITLE,
        "version": VERSION,
        "scientific_status": "VALIDATED_SIGNED_SIX_COMPONENT_THIRD_CHART_TERMINAL_ENDPOINT_BOX_CERTIFIED" if passed else "THIRD_CHART_SIGNED_ENDPOINT_INCONCLUSIVE_FAIL_CLOSED",
        "step_count": steps,
        "total_certified_time": str(total_time),
        "terminal_endpoint_box": certificate["terminal_endpoint_box"],
        "maximum_endpoint_absolute_coordinate": str(max_abs),
        "v0927_scalar_reachable_radius": str(scalar_radius),
        "inner_domain_radius": str(domain_radius),
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "signed_six_component_terminal_endpoint_box_certified": passed,
        "sharp_trajectory_midpoint_certified": False,
        "fourth_recenter_target_ready": passed,
        "complete_child_certified": False,
        "global_flow_claimed": False,
        "certificate": str(cert_path),
        "certificate_sha256": sha256_file(cert_path),
        "next_required_step": "use the complete signed endpoint box as the fourth same-chart parametric normal-root target, then certify its new tangent/normal frame",
        "claim_boundary": certificate["claim_boundary"],
        "elapsed_seconds": time.time() - started,
        "environment": {"python": platform.python_version(), "platform": platform.platform()},
    }
    result["report_sha256_before_self_field"] = sha256_json(result)
    atomic_json(out / "run_summary.json", result)
    return result


def main() -> int:
    args, ignored = parse()
    if ignored:
        print(f"[notice] ignored notebook/kernel arguments: {ignored}")
    try:
        result = run(args)
        print("=" * 112)
        print(f"{TITLE} v{VERSION}")
        print("=" * 112)
        print(json.dumps(result, indent=2, allow_nan=False))
        return 0 if result["all_scientific_gates_pass"] else 2
    except Exception as exc:
        print(json.dumps({"scientific_status": "V0928_FAILED_CLOSED", "error_type": type(exc).__name__, "error": str(exc)}, indent=2))
        return 2


if __name__ == "__main__":
    code = main()
    if "ipykernel" not in sys.modules and "google.colab" not in sys.modules:
        raise SystemExit(code)
